#include <stdint.h>

int main(void)
{
   uint32_t *pClockCtrlreg = (uint32_t*)0x40023830;
   uint32_t *pPortAModereg = (uint32_t*)0x40020000;
   uint32_t *pPortAOutreg = (uint32_t*)0x40020014;

   //1. enable the clock for GPIOA peripheral in the AHB1ENR
   *pClockCtrlreg |= 0X01;

   //2. Configure the mode of the IO pin as output
   //a. clear the 10th and 11th bit position (CLEAR)
   *pPortAModereg &= ~(0X00000C00);

   //b. make 10 bit position as 1 (SET)
   *pPortAModereg |= 0X00000400;

   //3. SET 5th bit bit of output data register to make I/O pin-5 as HIGH
   *pPortAOutreg |= 0x0020;

   while(1);

}




